script:
function showTab(name,btn){document.querySelectorAll('.tab-btn').forEach(function(b){b.dataset.active='false'});document.querySelectorAll('.tab-panel').forEach(function(p){p.hidden=true});document.getElementById('panel-'+name).hidden=false;btn.dataset.active='true'}
function formatNumber(n){return Number.isInteger(n)?n.toString():parseFloat(n.toFixed(4)).toString()}
function calcBasic(){var p=parseFloat(document.getElementById('basic-percent').value),n=parseFloat(document.getElementById('basic-number').value),r=document.getElementById('basic-result'),f=document.getElementById('basic-formula');if(!isNaN(p)&&!isNaN(n)){var res=(p/100)*n;r.textContent=formatNumber(res);f.textContent='('+p+' \u00f7 100) \u00d7 '+n+' = '+formatNumber(res)}else{r.textContent='?';f.textContent=''}}
function calcReverse(){var part=parseFloat(document.getElementById('reverse-part').value),whole=parseFloat(document.getElementById('reverse-whole').value),r=document.getElementById('reverse-result'),f=document.getElementById('reverse-formula');if(!isNaN(part)&&!isNaN(whole)&&whole!==0){var res=(part/whole)*100;r.textContent=formatNumber(res)+'%';f.textContent='('+part+' \u00f7 '+whole+') \u00d7 100 = '+formatNumber(res)+'%'}else{r.textContent='?';f.textContent=''}}
function calcChange(){var from=parseFloat(document.getElementById('change-from').value),to=parseFloat(document.getElementById('change-to').value),r=document.getElementById('change-result'),f=document.getElementById('change-formula');if(!isNaN(from)&&!isNaN(to)&&from!==0){var pct=((to-from)/Math.abs(from))*100,sign=pct>=0?'+':'';r.textContent=sign+formatNumber(pct)+'%';f.textContent='(('+to+' - '+from+') \u00f7 '+from+') \u00d7 100 = '+sign+formatNumber(pct)+'%'}else{r.textContent='?';f.textContent=''}}

function calculate() {
  const o = parseFloat(document.getElementById('old_value').value);
  const n = parseFloat(document.getElementById('new_value').value);
  const r = document.getElementById('result');
  const f = document.getElementById('formula_display');
  const t = document.getElementById('change_type');
  if (!isNaN(o) && !isNaN(n) && o !== 0) {
    const diff = n - o;
    const pct = (diff / Math.abs(o)) * 100;
    const sign = pct >= 0 ? '+' : '';
    r.textContent = sign + formatNumber(pct) + '%';
    if (t) t.textContent = pct >= 0 ? 'Increase' : 'Decrease';
    if (f) f.textContent = '((' + n + ' - ' + o + ') ÷ ' + o + ') × 100 = ' + sign + formatNumber(pct) + '%';
  } else {
    r.textContent = '?';
    if (t) t.textContent = '?';
    if (f) f.textContent = '';
  }
}

function formatNumber(n) {
  return Number.isInteger(n) ? n.toString() : parseFloat(n.toFixed(4)).toString();
}

function calculate() {
  const e = parseFloat(document.getElementById('experimental').value);
  const t = parseFloat(document.getElementById('theoretical').value);
  const r = document.getElementById('result');
  const f = document.getElementById('formula_display');
  const a = document.getElementById('absolute_error');
  if (!isNaN(e) && !isNaN(t) && t !== 0) {
    const abs = Math.abs(e - t);
    const pct = (abs / Math.abs(t)) * 100;
    r.textContent = formatNumber(pct) + '%';
    if (a) a.textContent = formatNumber(abs);
    if (f) f.textContent = '(|' + e + ' - ' + t + '| ÷ |' + t + '|) × 100 = ' + formatNumber(pct) + '%';
  } else {
    r.textContent = '?';
    if (a) a.textContent = '?';
    if (f) f.textContent = '';
  }
}

function formatNumber(n) {
  return Number.isInteger(n) ? n.toString() : parseFloat(n.toFixed(4)).toString();
}
